foreach ($m in $moves) {
  $src=$m[0]; $dst=$m[1]
  if (-not (Test-Path -LiteralPath $src)) { Write-Warning "Missing: $src"; continue }
  if (Test-Path -LiteralPath $dst) { Write-Warning "Exists, skipped: $dst"; continue }
  New-Item -ItemType Directory -Force -Path (Split-Path -LiteralPath $dst) | Out-Null
  Move-Item -LiteralPath $src -Destination $dst
}
Write-Host 'Undo complete.'
